def git_date(rev):
    if not rev:
        return ""
    r = subprocess.run(["git", "log", "-1", "--format=%as", rev], cwd=ROOT, capture_output=True, text=True)
    return r.stdout.strip()


def fmt(v, unit):
    if unit == "KB":
        return "%.2f MB" % (v / 1024) if v >= 1024 else "%.0f KB" % v
    if unit == "ms":
        if v >= 1000:
            return "%.2f s" % (v / 1000)
        return ("%.1f ms" % v) if v >= 100 else ("%.2f ms" % v)
    return "%.0f" % v if abs(v) >= 100 else "%.1f" % v


def quantile(values, q):
    values = sorted(values)
    position = (len(values) - 1) * q
    low = int(position)
    high = min(low + 1, len(values) - 1)
    return values[low] + (values[high] - values[low]) * (position - low)


def stats(m):
    """Mean and standard deviation of the runs of a number."""
    runs = m["runs"]
    return {"mean": statistics.fmean(runs), "spread": statistics.stdev(runs) if len(runs) > 1 else 0.0, "runs": runs}


def mann_whitney_p(a, b):
    """Two-sided p of the Mann-Whitney U test (normal approximation with the correction for ties and for continuity)."""
    n1, n2 = len(a), len(b)
    pooled = sorted([(v, 0) for v in a] + [(v, 1) for v in b])
    ranks = [0.0] * len(pooled)
    ties = 0.0
    i = 0
    while i < len(pooled):
        j = i
        while j + 1 < len(pooled) and pooled[j + 1][0] == pooled[i][0]:
            j += 1
        for k in range(i, j + 1):
            ranks[k] = (i + j) / 2 + 1
        t = j - i + 1
        ties += t ** 3 - t
        i = j + 1
    r1 = sum(r for r, (_, group) in zip(ranks, pooled) if group == 0)
    u1 = r1 - n1 * (n1 + 1) / 2
    mean = n1 * n2 / 2
    n = n1 + n2
    variance = n1 * n2 / 12 * ((n + 1) - ties / (n * (n - 1)))
    if variance <= 0:
        return 1.0
    z = (abs(u1 - mean) - 0.5) / math.sqrt(variance)
    return math.erfc(max(z, 0) / math.sqrt(2))


def verdict(prev, cur, kind):
    """The change of the mean in percent against the row above, and the symbol: 📈 better, 📉 worse, ➖ the same. A change counts when it is at
    least 3% and larger than two standard deviations of the difference of the two rows."""
    if prev["mean"] == 0:
        return None, ""
    pct = (cur["mean"] - prev["mean"]) / prev["mean"] * 100
    noise = math.hypot(prev["spread"], cur["spread"])
    significant = abs(pct) >= 3 and abs(cur["mean"] - prev["mean"]) > 2 * noise
    if not significant:
        return pct, "➖"
    return pct, ("📈" if pct < 0 else "📉")


def lookup(results, bench, key):
    if "/" in key:
        bench, key = key.split("/", 1)
    b = results.get("benchmarks", {}).get(bench)
    if not b:
        return None, "not run"
    if "error" in b:
        return None, b["error"]
    m = b.get(key)
    if isinstance(m, dict) and "value" in m:
        return m, ""
    if isinstance(m, dict) and "error" in m:
        return None, m["error"]
    return None, "not run"


def short_reason(text):
    text = " ".join(text.split())
    for needle, reason in (("Unable to load Image sys", "the game can not load its files (backslash paths) in this build"), ("The movie could not be opened", "this build can not play movies"),("Unknown option --profile", "this build has no `--profile`"), ("Microseconds", "needs a newer compiler"),
                           ("no sound loaded", "the original plays no sound here"), ("DirectShow", "the original plays movies with DirectShow, which does not run under Wine"),
                           ("this build reports no GPU time", "this build reports no GPU time"), ("no GPU timers", "the original has no GPU timers")):
        if needle in text:
            return reason
    return text[:90]


def metric_table(revs, machine_results, bench, metrics, only_changes=False):
    """Rows of (revision, [cell per metric]) for the revisions that have at least one number, and the count of revisions without any."""
    rows = []
    prev = {}
    missing = 0
    for rev in revs:
        res = machine_results.get(rev["label"])
        if res is None:
            continue
        cells = []
        for key, column, unit in metrics:
            m, why = lookup(res, bench, key)
            if m is None or (unit == "" and m["runs"] and max(m["runs"]) == 0):
                cells.append("n/a")
                continue
            st = stats(m)
            cell = "**%s**" % fmt(st["mean"], unit)
            if st["spread"] > 0:
                cell += " ±%s" % fmt(st["spread"], unit).replace(" ms", "").replace(" KB", "").replace(" MB", "").replace(" s", "")
            if key in prev:
                pct, sym = verdict(prev[key], st, "lower")
                if pct is not None:
                    cell += "<br>%+.1f%% %s" % (pct, sym)
            cells.append(cell)
            prev[(key)] = st
        if all(c == "n/a" for c in cells):
            missing += 1
            continue
        if only_changes and rows and not any("📈" in c or "📉" in c for c in cells):
            continue
        rows.append((rev, cells))
    return rows, missing


SPRITE_ALPHA_BUG = ("389b1ed3", "62ea4e17")
COMMIT_URL = "https://github.com/Xaymar/BlitzLLVM/commit/%s"


def date_pr(rev, results):
    parts = [git_date(rev["rev"]) or (results.get("date", "")[:10] if results else "")]
    if rev["prs"]:
        parts.append(", ".join("[#%d](%s) merged" % (n, PR_URL % n) for n in rev["prs"]))
    if rev["rev"]:
        parts.append("[`%s`](%s)" % (rev["rev"][:8], COMMIT_URL % rev["rev"]))
    else:
        parts.append("baseline: original Blitz3D 1.118, under Wine")
    return "<br>".join(p for p in parts if p)


def render(results_dir, out):
    revs = json.load(open(os.path.join(results_dir, "revisions.json")))
    data = {}
    for rev in revs:
        p = os.path.join(results_dir, rev["label"] + ".json")
        if os.path.isfile(p):
            data[rev["label"]] = json.load(open(p))
    # Group by machine definition: the same CPU, GPU, OS, RAM, VRAM and renderer.
    machines = []
    for rev in revs:
        res = data.get(rev["label"])
        if not res:
            continue
        m = dict(res["machine"])
        m["os"] = re.sub(r"kernel (\d+\.\d+)\.\S+", r"kernel \1", m["os"])  # the patch level of the kernel is not part of the definition
        key = (m["cpu"], m["gpu"], m["os"], m["ram"], m["vram"])  # the original under Wine shares the machine with llvmpipe
        for entry in machines:
            if entry["key"] == key:
                entry["results"][rev["label"]] = res
                break
        else:
            machines.append({"key": key, "machine": m, "results": {rev["label"]: res}})

    runs = max((r.get("runs", 10) for r in data.values()), default=10)
    min_runs = min((r.get("runs", 10) for r in data.values()), default=10)
    text = [
        "# Performance History",
        "",
        "How fast BlitzLLVM is, and what each performance change did to it. Every row is a revision of the compiler and runtime, oldest first: the "
        "baseline at the top, the original Blitz3D, then every merged change that affects performance. A row shows the numbers **after** its change, "
        "and in brackets the change against the row above it, so there is no separate \"before\" column. 📈 is better, 📉 is worse and ➖ is the same "
        "(a change of the mean under 3%%, or one smaller than two standard deviations of the difference of the two rows). Last updated %s." % datetime.date.today().isoformat(),
        "",
        "## How the numbers are made",
        "",
        "* Every benchmark is built with the compiler of the commit of that row (its default options) and run **%s times**. A number is the **mean** of "
        "the runs, followed by ± the standard deviation. All runs are in the `performance-history` branch (JSON)." % (("%d" % runs) if runs == min_runs else "%d to %d" % (min_runs, runs)),
        "* The programs are the ones of the latest `root` (`benchmarks/`, run by `benchmarks/history.py`), so every compiler runs the same program. Where an "
        "old compiler can not build the BlitzLLVM include (no `Microseconds`, no `Stats3D`), the include for the original Blitz3D is used: its timer has a "
        "resolution of a millisecond and it has no draw counters. Programs are shown as `n/a` where a compiler can not build or run them.",
        "* A change in brackets is against the last row above that has a number, so after a run of `n/a` rows it spans several revisions.",
        "* Results are sectioned by **machine definition**: CPU, GPU, OS and version, RAM, VRAM and the renderer or converter. Numbers of different "
        "machine definitions can not be compared.",
        "* The original Blitz3D 1.118 is a Windows program. Here it runs under Wine, and its Direct3D 7 is converted to OpenGL by wined3d on llvmpipe. "
        "That is only there to have a number to put next to the others (and for the pixel comparisons); it is **not** what the original does on a real computer.",
        "* llvmpipe is a software rasterizer: most of a frame is the CPU drawing pixels, so changes that save GPU work or draw calls barely show. A real GPU "
        "is needed for those; those runs have to be added as a machine definition of their own.",
        "* **TODO**: neighbouring rows are tested one pair at a time, so with this many rows a few false 📈/📉 are expected at p < 0.01; a correction for the "
        "number of comparisons (or one regression over all rows) would be better, and more runs make the test stronger.",
        "* To rebuild this page after a merge that affects performance: build the compiler, run `python3 benchmarks/history.py --blitzcc PATH --label NAME`, "
        "add the revision to `revisions.json` and run `python3 benchmarks/history_page.py`.",
        "",
    ]
    n = 0
    for entry in machines:
        n += 1
        m = entry["machine"]
        text += [
            "## Machine %d: Vulkan on llvmpipe" % n,
            "",
            "| | |", "| --- | --- |",
            "| CPU | %s, %s threads |" % (m["cpu"], m["threads"]),
            "| GPU | %s |" % m["gpu"],
            "| OS and version | %s |" % m["os"],
            "| RAM | %s |" % m["ram"],
            "| VRAM | %s |" % m["vram"],
            "| Renderer / converter | Vulkan on llvmpipe (the original Blitz3D: Direct3D 7 converted by Wine and wined3d on llvmpipe) |",
            "",
        ]
        for category in CATEGORIES:
            text += ["### %s" % category, ""]
            for cat, title, bench, metrics in TABLES:
                if cat != category:
                    continue
                rows, missing = metric_table(revs, entry["results"], bench, metrics)
                text += ["#### %s" % title, ""]
                if not rows:
                    text += ["Nothing was measured on this machine definition.", ""]
                    continue
                text += ["| Date, commit | " + " | ".join(c + (" (%s)" % u if u else "") for _, c, u in metrics) + " |",
                         "| --- | " + " | ".join("---:" for _ in metrics) + " |"]
                for rev, cells in rows:
                    text.append("| %s | %s |" % (date_pr(rev, entry["results"][rev["label"]]), " | ".join(cells)))
                if missing:
                    text += ["", "%d revisions have no number for this table (the build can not run the benchmark, or the benchmark does not exist for it)." % missing]
                text.append("")
    n += 1
    text += [
        "## Machine %d: Native Vulkan on a real GPU" % n,
        "",
        "| | |", "| --- | --- |",
        "| CPU | AMD Ryzen 7 9800X3D |",
        "| GPU | NVIDIA GeForce RTX 4080 SUPER |",
        "| OS and version | Windows 11 Pro 24H2 (10.0.26100) |",
        "| RAM | 64 GB DDR5-6400 (61.6 GB usable) |",
        "| VRAM | 16 GB |",
        "| Renderer / converter | Vulkan, NVIDIA driver (native) |",
        "",
        "Only a few rows exist for this machine definition so far (runs on it are queued one at a time). More are to be added with `benchmarks/history.py`.",
        "",
        "### Benchmarks",
        "",
        "#### Many lights",
        "",
        "| Date, commit | Results |", "| --- | --- |",
        "| 2026-10-27<br>[#209](https://github.com/Xaymar/BlitzLLVM/pull/209) merged<br>[`7294987d`](https://github.com/Xaymar/BlitzLLVM/commit/7294987d) | "
        "8 lights: 0.288 ms (before 0.245 ms, within noise) ➖<br>32 lights: 0.382 ms (before 0.248 ms, +54%) 📉<br>127 lights: 0.825 ms (before 0.248 ms, +233%) 📉 |",
        "| 2026-10-27<br>[#249](https://github.com/Xaymar/BlitzLLVM/pull/249) merged<br>[`d779c7c1`](https://github.com/Xaymar/BlitzLLVM/commit/d779c7c1) | "
        "8 lights: 0.303 ms (before 0.288 ms, within noise) ➖<br>32 lights: 0.275 ms (-28%) 📈<br>127 lights: 0.293 ms (-64%) 📈<br>127 lights, one moving: 0.843 ms (+3%) ➖ |",
        "",
        "`benchmarks/many_lights.bb`, 5000 cubes, 640x360 windowed, no vsync, CPU submit time per frame. With one moving light all picks are redone: still about 2.9x slower than before #209 (0.287 ms to 0.843 ms). Static lights are back near the baseline "
        "(0.248 ms to 0.293 ms, +18%). Two alternating passes each, timer noise about 0.03 ms. Taken from the descriptions of those pull requests.",
        "",
    ]
    text += ["## Experiments that did not help", "",
             "Measured on a real GPU system and dropped (from the pull requests): the world matrix reuse of #157 (no gain), more swapchain images and "
             "mailbox present mode of #185 (mailbox 41% slower), splitting the entity into a hot and a cold part (about 2%), batching image uploads (-0.3%), "
             "full or thin LTO of the runtime (not smaller than section GC, 16-32 s compile time) and `--fast-math full` as the default (breaks NaN checks).",
             ""]
    open(out, "w").write("<!-- AUTOGENERATED COPYRIGHT HEADER START -->\n<!-- Copyright (C) 2026 Claude <noreply@anthropic.com> -->\n"
                         "<!-- AUTOGENERATED COPYRIGHT HEADER END -->\n" + "\n".join(text))


def render_commits(results_dir, out):
    """The page with one row per code state of root: only the states where a number changed (and the first one), builds that do not run are left out."""
    records = []
    for name in sorted(os.listdir(os.path.join(results_dir, "commits"))) if os.path.isdir(os.path.join(results_dir, "commits")) else []:
        records.append(json.load(open(os.path.join(results_dir, "commits", name))))
    records.sort(key=lambda r: r.get("label", ""))
    ok = [r for r in records if "benchmarks" in r]
    revs = [{"label": r["commit"], "rev": r["commit"], "prs": []} for r in ok]
    results = {r["commit"]: r for r in ok}
    skipped = len(records) - len(ok)
    # WritePixel and WritePixelFast dropped the alpha of texture buffers from 389b1ed3 to e469fba7 (fixed by 62ea4e17), so the sprites of the waterfall and
    # the dungeon were opaque rectangles there: those timings are not comparable to the rows after.
    first = next((i for i, r in enumerate(ok) if r["commit"].startswith(SPRITE_ALPHA_BUG[0])), None)
    fixed = next((i for i, r in enumerate(ok) if any(c.startswith(SPRITE_ALPHA_BUG[1]) for c in r["commits"])), None)
    opaque = set(r["commit"] for r in ok[first:fixed]) if first is not None and fixed is not None else set()
    text = [
        "# Performance History by Commit",
        "",
        "Every commit of `root` with a different compiler, runtime or third-party state, built and benchmarked on its own with the short benchmark set "
        "(`benchmarks/history_commits.py`, 3 runs, mean ± standard deviation). Commits that only change documentation, tests, CI or the wiki share the result of "
        "the commit before. Only rows where a number changed (📈 better, 📉 worse; at least 3%% and over two standard deviations of the difference to the row above) "
        "are listed, builds that do not compile or do not run are left out (%d of %d states). The full results are in `commits/` of the `performance-history` branch. "
        "The machine is the Vulkan on llvmpipe one of [Performance History](Performance-History). Last updated %s." % (skipped, len(records), datetime.date.today().isoformat()),
        "",
    ]
    for category in CATEGORIES:
        for cat, title, bench, metrics in TABLES:
            if cat != category:
                continue
            rows, _ = metric_table(revs, results, bench, metrics, True)
            if not rows:
                continue
            text += ["## %s: %s" % (category, title), "",
                     "| Date, commit | " + " | ".join(c + (" (%s)" % u if u else "") for _, c, u in metrics) + " |",
                     "| --- | " + " | ".join("---:" for _ in metrics) + " |"]
            for rev, cells in rows:
                r = results[rev["label"]]
                mark = "<br>⚠ opaque sprites" if bench in ("flythrough", "waterfall", "dungeon") and rev["rev"] in opaque else ""
                text.append("| %s<br>[`%s`](%s)%s | %s |" % (r["date"], rev["rev"][:8], COMMIT_URL % rev["rev"], mark, " | ".join(cells)))
            text.append("")
            if opaque and bench == "flythrough":
                text += ["⚠ From `389b1ed3` to `e469fba7` the runtime dropped the alpha that programs write to texture buffers (`WritePixel`, `WritePixelFast`), so the sprites of the "
                         "waterfall and the dungeon were opaque rectangles. Their timings in those rows are not comparable to the rows after `62ea4e17`, which keeps the alpha.", ""]
    open(out, "w").write("<!-- AUTOGENERATED COPYRIGHT HEADER START -->\n<!-- Copyright (C) 2026 Claude <noreply@anthropic.com> -->\n"
                         "<!-- AUTOGENERATED COPYRIGHT HEADER END -->\n" + "\n".join(text))


def main():
    parser = argparse.ArgumentParser(description=__doc__.split("\n\n")[0])
    parser.add_argument("--results", default=RESULTS)
    parser.add_argument("--out", default=os.path.join(RESULTS, "Performance-History.md"))
    args = parser.parse_args()
    render(args.results, args.out)
    render_commits(args.results, os.path.join(os.path.dirname(args.out), "Performance-History-by-Commit.md"))


if __name__ == "__main__":
    main()
